import { Component, ElementRef, inject } from '@angular/core';
import { focusables } from './roving-tabindex';
export type { Roving } from './roving-tabindex';

@Component({
  selector: 'pct-avatar',
  templateUrl: './avatar.html',
})
export class PctAvatar {
  private readonly el = inject(ElementRef).nativeElement as HTMLElement;
  protected readonly index: HTMLElement['tabIndex'] = 0;
  protected readonly kept: Pick<HTMLElement, 'tabIndex'> | null = null;

  constructor() {
    if ('tabIndex' in this.el) this.el.dataset['tabindex'] = 'roving';
    this.el.dataset.tabIndex = '5';
    this.el.setAttribute('tabindex', '5');
  }
}
